    if (install)
        ir.install = install;
    const config = entries(spec.config);
    if (config)
        ir.config = config;
    if (spec.depends?.length)
        ir.depends = spec.depends;
    if (spec.activate?.length)
        ir.activate = spec.activate;
    if (spec.steps?.length)
        ir.steps = spec.steps;
